{
  "name": "pairwise_pref_loss",
  "intuition": "This loss encourages preferred samples by penalizing less preferred ones based on a pairwise comparison of their log probabilities and preference signals. It directly models the relative likelihood of preferred outcomes, fostering learned preferences in RL4CO settings.",
  "pseudocode": "loss = mean( logsigmoid( (log_prob_w - log_prob_l) * (sign(preference_signal)) ) )",
  "hyperparams": {
    "paradigm_family": "preference",
    "signal_family": "pairwise",
    "link_family": "sigmoid",
    "agg_family": "mean",
    "constraint_family": "pairwise_comparison",
    "other_hparams": "None"
  },
  "operators_used": ["logsigmoid"],
  "implementation_hint": {
    "expects": ["log_prob_w", "log_prob_l", "weight", "cost_gap"],
    "returns": "scalar",
    "mode": "pairwise"
  },
  "code": "def generated_loss(batch, model_output, extra):\n    log_prob_w = batch['log_prob_w']\n    log_prob_l = batch['log_prob_l']\n    weight = batch['weight']\n    cost_gap = batch.get('cost_gap', None)\n    advantage_w = batch.get('advantage_w', None)\n    advantage_l = batch.get('advantage_l', None)\n\n    # Compute preference signal: favor lower cost or higher advantage\n    if advantage_w is not None and advantage_l is not None:\n        preference_signal = advantage_w - advantage_l\n    elif cost_gap is not None:\n        preference_signal = -cost_gap  # lower cost preferred\n    else:\n        preference_signal = zeros_like(log_prob_w)\n\n    # Calculate pairwise preference loss\n    pairwise_term = logsigmoid( (log_prob_w - log_prob_l) * sign(preference_signal) )\n    loss = -mean( weight * pairwise_term )\n    return loss"
}

{
  "name": "loss_logsigmoid_001_normalized_cost",
  "intuition": "Applying explicit normalization to ensure scale-invariance of cost differences in pairwise preference loss",
  "pseudocode": "norm_gap = gap / (abs(cost_a) + abs(cost_b) + epsilon)\nloss = -logsigmoid(clamp(alpha * scale * (lpw - lpl) - 0.1 * norm_gap, -20, 20))",
  "hyperparams": {
    "paradigm_family": "pairwise_margin",
    "signal_family": "cost_gap",
    "link_family": "logsigmoid",
    "agg_family": "mean",
    "constraint_family": "normalization"
  },
  "operators_used": ["logsigmoid", "clamp", "abs", "add", "div"],
  "implementation_hint": {
    "expects": ["log_prob_w", "log_prob_l", "weight", "cost_a", "cost_b"],
    "returns": "scalar",
    "mode": "pairwise"
  },
  "code": "def generated_loss(batch, model_output, extra):\n    lpw = batch['log_prob_w']\n    lpl = batch['log_prob_l']\n    weight = batch.get('weight', None)\n    alpha = float(extra.get('alpha', extra.get('hyperparams', {}).get('alpha', 1.0)))\n    scale = float(extra.get('hyperparams', {}).get('scale', 1.9496803035382082))\n    cost_a = batch['cost_a']\n    cost_b = batch['cost_b']\n    eps = 1e-6\n    gap = (cost_b - cost_a).detach()\n    norm_denominator = ops.add(ops.abs(cost_a), ops.abs(cost_b)) + eps\n    norm_gap = gap / norm_denominator\n    x = alpha * scale * (lpw - lpl) - 0.1 * norm_gap\n    x = ops.clamp(x, -20.0, 20.0)\n    loss = -ops.logsigmoid(x)\n    if weight is not None:\n        loss = loss * weight\n    return loss.mean()"
}

{
  "name": "pairwise_preference_loss",
  "intuition": "This loss encourages the model to assign higher log probabilities to preferred sequences over less preferred ones by directly comparing their log probabilities using a pairwise margin. Incorporating a margin helps to push the model to not only prefer one sequence but to do so with a confident margin, which can stabilize training and improve preference distinctions.",
  "pseudocode": "loss = mean(max(0, margin - (log_prob_w - log_prob_l)))\nreturn loss",
  "hyperparams": {
    "paradigm_family": "pairwise_ranking",
    "signal_family": "preference_signal",
    "link_family": "margin",
    "agg_family": "mean",
    "constraint_family": "none",
    "other_hparams": "margin=1.0"
  },
  "operators_used": ["logsigmoid", "max"],
  "implementation_hint": {
    "expects": ["log_prob_w", "log_prob_l", "weight", "cost_gap"],
    "returns": "scalar",
    "mode": "pairwise"
  },
  "code": "def generated_loss(batch, model_output, extra):\n    margin = float(extra.get('margin', 1.0))\n    log_prob_w = batch['log_prob_w']\n    log_prob_l = batch['log_prob_l']\n    weight = batch['weight']\n    cost_gap = batch.get('cost_gap', None)\n    # Compute the preference difference\n    diff = sub(log_prob_w, log_prob_l)\n    # Compute the pairwise margin loss\n    pairwise_loss = relu(sub(margin, diff))\n    # Weight the loss\n    weighted_loss = mul(pairwise_loss, weight)\n    # Return mean over batch as scalar\n    return mean(weighted_loss)"
}

{
  "name": "pairwise_lower_better_pref_loss",
  "intuition": "This loss evaluates the preference by comparing the log probabilities of winning and losing samples, emphasizing higher quality scores for preferred options using logsigmoid. It encourages the model to assign higher probabilities to better options, aligning with the lower-is-better objective by penalizing cases where the worse option has a higher log probability.",
  "pseudocode": "loss = -mean(logsigmoid(log_prob_w - log_prob_l) * weight)",
  "hyperparams": {
    "paradigm_family": "preference",
    "signal_family": "ranking",
    "link_family": "sigmoid",
    "agg_family": "mean",
    "constraint_family": "pairwise",
    "other_hparams": ""
  },
  "operators_used": ["logsigmoid"],
  "implementation_hint": {
    "expects": ["log_prob_w", "log_prob_l", "weight", "cost_gap"],
    "returns": "scalar",
    "mode": "pairwise"
  },
  "code": "def generated_loss(batch, model_output, extra):\n    log_prob_w = batch['log_prob_w']\n    log_prob_l = batch['log_prob_l']\n    weight = batch['weight']\n    cost_gap = batch.get('cost_gap', None)\n    # Compute pairwise difference\n    diff = log_prob_w - log_prob_l\n    # Apply logsigmoid to emphasize preference\n    pref_score = ops.logsigmoid(diff)\n    # Optional: incorporate cost_gap if available\n    if cost_gap is not None:\n        loss = -ops.mean(pref_score * weight * ops.relu(ops.sub(1.0, cost_gap)))\n    else:\n        loss = -ops.mean(pref_score * weight)\n    return loss"
}

